.twyne-manual {
  min-height: 100vh;
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font: 1rem/1.75 var(--font-serif);
}

.manual-shell {
  max-width: 76rem;
  margin: 0 auto;
  padding: 3rem 2.5rem 4rem;
}

.manual-masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  padding-bottom: 2.5rem;
  margin-bottom: 3rem;
  border-bottom: 3px double var(--color-ink);
}

.manual-eyebrow,
.manual-chapter {
  margin: 0 0 1rem;
  color: var(--color-ink-light);
  font: 500 0.875rem/1.4 var(--font-sans);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.manual-masthead h1 {
  margin: 0;
  font: 700 3rem/1.2 var(--font-display);
  letter-spacing: -0.035em;
}

.manual-deck {
  max-width: 52ch;
  margin: 1rem 0 0;
  color: var(--color-ink-light);
  font: italic 1.0625rem/1.7 var(--font-serif);
}

.manual-desk-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-height: 2.75rem;
  font: 500 0.875rem/1.4 var(--font-sans);
}

.manual-layout {
  display: grid;
  grid-template-columns: 15.5rem minmax(0, 1fr);
  align-items: start;
  gap: 4rem;
}

.manual-contents {
  position: sticky;
  top: 1.5rem;
  max-height: calc(100dvh - 3rem);
  overflow-y: auto;
  padding: 0.125rem 0.5rem 0.5rem 0;
  font-family: var(--font-sans);
}

.manual-contents summary {
  cursor: pointer;
  padding: 0.5rem 0;
  color: var(--color-ink);
  font-size: 0.9375rem;
  font-weight: 600;
}

.manual-contents-title {
  margin: 0;
  padding: 0.5rem 0;
  font: 600 0.9375rem/1.75 var(--font-sans);
}

.manual-mobile-contents {
  display: none;
}

.manual-contents-groups {
  margin-top: 1.25rem;
}

.manual-contents-group + .manual-contents-group {
  margin-top: 1.25rem;
}

.manual-contents-label {
  margin: 0 0 0.5rem;
  color: var(--color-ink-light);
  font-size: 0.875rem;
  font-weight: 600;
}

.manual-contents ol {
  list-style: none;
  margin: 0;
  padding: 0;
}

.twyne-manual .toc-link {
  display: flex;
  align-items: baseline;
  gap: 0.625rem;
  padding: 0.5rem 0;
  color: var(--color-ink-light);
  font-size: 0.875rem;
  line-height: 1.35;
  text-decoration: none;
}

.toc-link span {
  flex: 0 0 1.25rem;
  font-variant-numeric: tabular-nums;
}

.twyne-manual .toc-link:hover {
  color: var(--color-vermilion);
  text-decoration: underline;
  text-underline-offset: 0.2em;
}

.manual-house-link {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  margin-top: 1.25rem;
  font-size: 0.875rem;
}

.manual-content {
  min-width: 0;
  max-width: 70ch;
}

.manual-section {
  scroll-margin-top: 2rem;
  border-bottom: 1px solid var(--color-paper-3);
  padding-bottom: 3rem;
  margin-bottom: 3rem;
}

.manual-chapter {
  margin-bottom: 0.625rem;
}

.manual-h2 {
  margin: 0 0 1rem;
  font: 700 1.75rem/1.35 var(--font-display);
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.manual-h3 {
  margin: 1.75rem 0 0.625rem;
  font: 600 1.125rem/1.5 var(--font-display);
  text-wrap: balance;
}

.manual-lead {
  margin: 0 0 1.25rem;
  color: var(--color-ink-light);
  font: italic 1.0625rem/1.7 var(--font-serif);
}

.manual-p {
  margin: 0 0 1.125rem;
  line-height: 1.8;
}

.twyne-manual strong {
  font-weight: 600;
}

.manual-ul,
.manual-start {
  margin: 1rem 0 1.5rem;
  padding-left: 1.5rem;
}

.manual-ul li,
.manual-start li {
  padding-left: 0.25rem;
  margin-bottom: 0.75rem;
}

.manual-ul {
  list-style: disc;
}

.manual-start {
  list-style: decimal;
}

.manual-start li::marker {
  font-family: var(--font-sans);
  font-variant-numeric: tabular-nums;
}

.manual-callout {
  margin: 1.5rem 0 0;
  padding: 1.25rem 1.5rem;
  border-block: 1px solid var(--color-paper-3);
  background: var(--color-paper);
}

.manual-callout p {
  margin: 0;
  color: var(--color-ink-light);
  font-size: 0.9375rem;
  line-height: 1.75;
}

.twyne-manual a:not(.btn-paper, .toc-link, .manual-skip) {
  color: var(--color-ink);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.2em;
}

.twyne-manual a:not(.btn-paper, .toc-link):hover {
  color: var(--color-vermilion);
}

.twyne-manual :is(a, summary, input):focus-visible {
  outline: 2px solid var(--color-vermilion);
  outline-offset: 4px;
}

.manual-route {
  margin: 1.25rem 0 0;
  font: 500 0.9375rem/1.5 var(--font-sans);
}

.manual-inheritance {
  list-style: none;
  margin: 1.5rem 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-block: 1px solid var(--color-ink-light);
}

.manual-inheritance li {
  padding: 1.25rem 1rem;
}

.manual-inheritance li + li {
  border-left: 1px solid var(--color-paper-3);
}

.manual-inheritance strong {
  display: block;
  margin-bottom: 0.5rem;
  font: 600 0.9375rem/1.5 var(--font-sans);
}

.manual-inheritance span {
  display: block;
  color: var(--color-ink-light);
  font-size: 0.9375rem;
  line-height: 1.65;
}

.manual-terms {
  margin: 1.5rem 0;
}

.manual-terms > div {
  display: grid;
  grid-template-columns: 7rem minmax(0, 1fr);
  gap: 1rem;
  padding: 0.875rem 0;
  border-bottom: 1px solid var(--color-paper-3);
}

.manual-terms dt {
  font: 600 0.9375rem/1.7 var(--font-sans);
}

.manual-terms dd {
  margin: 0;
  font-size: 0.9375rem;
  color: var(--color-ink-light);
}

.manual-kbd {
  display: inline-block;
  padding: 0.125rem 0.375rem;
  border: 1px solid var(--color-paper-3);
  border-radius: 2px;
  background: var(--color-paper-2);
  font: 500 0.875rem/1.4 var(--font-sans);
}

.manual-platform {
  display: flex;
  flex-wrap: wrap;
  gap: 0 1.5rem;
  margin: 1rem 0 2rem;
  padding: 0;
  border: 0;
  font: 0.9375rem/1.5 var(--font-sans);
}

.manual-platform legend {
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.manual-platform label {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  gap: 0.625rem;
  cursor: pointer;
}

.manual-platform input {
  width: 1rem;
  height: 1rem;
  accent-color: var(--color-vermilion);
}

.manual-shortcuts h3 {
  color: var(--color-ink-light);
  font: 600 0.875rem/1.5 var(--font-sans) !important;
  letter-spacing: 0;
  text-transform: none;
}

.manual-shortcuts dd {
  font-size: 0.875rem;
}

.manual-shortcuts kbd {
  font: 500 0.875rem/1.4 var(--font-sans) !important;
}

.manual-colophon {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem 2rem;
  color: var(--color-ink-light);
  font: 0.875rem/1.5 var(--font-sans);
}

.manual-skip {
  position: fixed;
  top: 0.5rem;
  left: 0.5rem;
  z-index: var(--z-overlay);
  transform: translateY(-200%);
  padding: 0.75rem 1rem;
  background: var(--color-paper);
  color: var(--color-ink);
  font: 0.9375rem var(--font-sans);
}

.manual-skip:focus {
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .twyne-manual :is(a, input) {
    transition: none;
  }
}

@media (max-width: 960px) {
  .manual-shell {
    padding-inline: 1.5rem;
  }
  .manual-layout {
    grid-template-columns: 13rem minmax(0, 1fr);
    gap: 2rem;
  }
}

@media (max-width: 720px) {
  .manual-shell {
    padding: 1.5rem 1.25rem 2.5rem;
  }
  .manual-masthead {
    display: block;
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
  }
  .manual-masthead h1 {
    font-size: 2.25rem;
  }
  .manual-desk-link {
    margin-top: 1.25rem;
  }
  .manual-layout {
    display: block;
  }
  .manual-contents {
    position: static;
    max-height: none;
    overflow: visible;
    padding: 0 0 1.5rem;
    margin-bottom: 2rem;
    border-bottom: 1px solid var(--color-paper-3);
  }
  .manual-contents summary {
    min-height: 2.75rem;
  }
  .manual-desktop-contents {
    display: none;
  }
  .manual-mobile-contents {
    display: block;
  }
  .manual-contents-groups {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1.25rem 1rem;
  }
  .manual-contents-group + .manual-contents-group {
    margin-top: 0;
  }
  .twyne-manual .toc-link {
    min-height: 2.75rem;
  }
  .manual-content {
    max-width: none;
  }
  .manual-section {
    margin-bottom: 2rem;
    padding-bottom: 2rem;
  }
  .manual-h2 {
    font-size: 1.5rem;
  }
  .manual-inheritance {
    grid-template-columns: 1fr;
  }
  .manual-inheritance li + li {
    border-left: 0;
    border-top: 1px solid var(--color-paper-3);
  }
  .manual-terms > div {
    grid-template-columns: 6rem minmax(0, 1fr);
    gap: 0.75rem;
  }
  .manual-callout {
    padding: 1rem;
  }
}

@media print {
  .manual-shell {
    padding: 0;
  }
  .manual-layout {
    display: block;
  }
  .manual-content {
    max-width: none;
  }
  .manual-contents,
  .manual-desk-link,
  .manual-colophon,
  .manual-skip,
  #launch-film,
  .manual-platform {
    display: none;
  }
  .manual-h2,
  .manual-h3 {
    break-after: avoid;
  }
  .manual-callout,
  .manual-inheritance {
    break-inside: avoid;
  }
}

