import { component$, isDev, useVisibleTask$ } from "@qwik.dev/core";
import { RouterOutlet, useQwikRouter } from "@qwik.dev/router";
import { RouterHead } from "./components/router-head/router-head";
import { ConvexProvider } from "./utils/convex-context";
import { AuthProvider } from "./utils/auth-context";
import { PostHogProvider } from "./utils/posthog-context";
import { installLixAuthInterceptor } from "./utils/lix-auth";
import { GlobalConnectivityBanner } from "./components/ui/global-connectivity-banner";
import { GlobalApplicationToasts } from "./components/ui/global-application-toasts";
import { GlobalSpeechPlayer } from "./components/ui/global-speech-player";
import { LiveVoiceDesk } from "./components/ui/live-voice-desk";
import { UsageSyncController } from "./components/desk/usage-sync-controller";
import { AppI18nProvider } from "./i18n/provider";
import type { AppLocale, LanguagePreference } from "./i18n/locale";
import {
  THEME_BOOTSTRAP_SCRIPT,
  applyTheme,
  readThemePreference,
} from "./utils/theme";

import "./global.css";

const SERVICE_WORKER_REGISTER_SCRIPT = `
if ("serviceWorker" in navigator) {
  navigator.serviceWorker
    .register(${JSON.stringify(`${import.meta.env.BASE_URL}service-worker.js`)})
    .catch((error) => console.error("Twyne service worker registration failed", error));
}
`;

export default component$<{
  initialLocale?: AppLocale;
  initialPreference?: LanguagePreference;
}>((props) => {
  useQwikRouter({ viewTransition: true });

  const convexUrl = (import.meta.env.PUBLIC_CONVEX_URL ??
    import.meta.env.VITE_CONVEX_URL) as string | undefined;

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(() => {
    installLixAuthInterceptor();

    // The bootstrap script resolves "System" once, at load. Keep following the
    // OS afterwards, so flipping the machine to dark at dusk re-inks the room
    // without a reload. Explicit presets are left alone.
    const query = window.matchMedia("(prefers-color-scheme: dark)");
    const sync = () => {
      const preference = readThemePreference();
      if (preference.preset !== "system") return;
      applyTheme(preference, document.documentElement, query.matches);
    };
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  });

  return (
    <>
      <head>
        <meta charset="utf-8" />
        {/*
          Stamps the writer's palette onto <html> before the first paint.
          It has to be an inline script rather than a component: Qwik
          server-renders the document, so any QRL resumes long after the
          browser has already painted the default cream — which is exactly
          the flash this avoids. The source lives in `utils/theme.ts` so it
          cannot drift from `applyTheme`.
        */}
        <script
          data-theme-bootstrap
          dangerouslySetInnerHTML={THEME_BOOTSTRAP_SCRIPT}
        />
        {!isDev && (
          <link
            rel="manifest"
            href={`${import.meta.env.BASE_URL}manifest.json`}
          />
        )}
        {/* Editorial type stack — Libre Baskerville (display), Lora (body),
            DM Sans (UI), Special Elite (typewriter). Fraunces remains loaded
            for manuscripts that persisted the former display-font mark. */}
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link
          rel="preconnect"
          href="https://fonts.gstatic.com"
          crossOrigin="anonymous"
        />
        <link
          rel="stylesheet"
          href="https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=Libre+Baskerville:ital,wght@0,400;0,700;1,400&family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Special+Elite&display=swap"
        />
        <RouterHead />
      </head>
      <body lang={props.initialLocale ?? "en"}>
        <AppI18nProvider
          initialLocale={props.initialLocale ?? "en"}
          initialPreference={props.initialPreference ?? "auto"}
        >
          <GlobalConnectivityBanner />
          <GlobalApplicationToasts />
          <ConvexProvider url={convexUrl}>
            <AuthProvider>
              <PostHogProvider>
                <UsageSyncController />
                <RouterOutlet />
                {isDev && <PopmeltDev />}
                <GlobalSpeechPlayer />
                <LiveVoiceDesk />
                {!isDev && (
                  <script
                    type="module"
                    dangerouslySetInnerHTML={SERVICE_WORKER_REGISTER_SCRIPT}
                  />
                )}
              </PostHogProvider>
            </AuthProvider>
          </ConvexProvider>
        </AppI18nProvider>
      </body>
    </>
  );
});
"}

